const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const siteQueueManager = require("../utils/siteQueueManager");
const contextPool = require("../utils/contextPool");
const logger = require("../../../src/utils/logger");

// 预加载fakePage模板，避免每次请求都读取文件
let fakePageTemplate = null;
try {
  fakePageTemplate = fs.readFileSync(path.join(__dirname, "../data/fakePage.html"), 'utf8');
} catch (e) {
  console.error('Failed to load fakePage.html template');
}

// 是否启用上下文池（无代理时使用池，有代理时独立创建）
const ENABLE_CONTEXT_POOL = process.env.TURNSTILE_ENABLE_POOL !== 'false';

// 需要阻止的资源类型（减少内存和带宽消耗）
// 注意：不要阻止 stylesheet，Turnstile 可能需要它
const BLOCKED_RESOURCE_TYPES = new Set([
  'image', 'media', 'font'
]);

// 需要阻止的URL模式（广告、分析等无关资源）
const BLOCKED_URL_PATTERNS = [
  /google-analytics/i,
  /googletagmanager/i,
  /facebook.*pixel/i,
  /doubleclick/i,
  /hotjar/i,
  /mixpanel/i,
  /segment\.io/i,
  /optimizely/i,
  /newrelic/i,
  /sentry\.io/i
];

/**
 * 检查URL是否应该被阻止
 */
function shouldBlockUrl(url) {
  return BLOCKED_URL_PATTERNS.some(pattern => pattern.test(url));
}

/**
 * 验证Token格式是否正确（轻量级验证）
 */
function validateToken(token) {
  if (!token || typeof token !== 'string') return false;
  if (token.length < 800 || token.length > 1500) return false;
  if (!token.startsWith('0.')) return false;
  if (token.split('.').length < 3) return false;
  return true;
}

function solveTurnstileMin({ url, proxy, siteKey, requestId }) {
  return new Promise(async (resolve, reject) => {
    if (!url) return reject("Missing url parameter");
    if (!siteKey) return reject("Missing siteKey parameter");

    const reqId = requestId || crypto.randomBytes(8).toString('hex');
    const startTime = Date.now();
    let context = null;
    let page = null;
    let timeoutId = null;
    let isResolved = false;
    let usePool = false; // 是否使用了上下文池

    // 统一的清理函数
    const cleanup = async (success = false) => {
      if (isResolved) return;
      isResolved = true;

      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }

      // 先清理page
      if (page) {
        try {
          await page.close().catch(() => {});
        } catch (e) {}
        page = null;
      }

      // 释放上下文
      if (usePool) {
        // 使用池：释放回池（池会负责清理页面）
        await contextPool.release(reqId, success);
      } else if (context) {
        // 独立上下文：直接关闭
        try {
          await context.close().catch(() => {});
        } catch (e) {}
      }
      context = null;

      // 释放队列槽位
      siteQueueManager.releaseSlot(url, siteKey, reqId, success, Date.now() - startTime);
    };

    // 加入站点队列
    const queueResult = await siteQueueManager.queueRequest(url, siteKey, reqId);
    if (queueResult.timeout) {
      return reject(`Queue timeout for request ${reqId}`);
    }

    try {
      // 获取浏览器上下文
      // 有代理时：创建独立上下文（代理配置无法复用）
      // 无代理时：使用上下文池
      if (proxy) {
        // 有代理 - 创建独立上下文
        const contextOptions = { proxyServer: `http://${proxy.host}:${proxy.port}` };
        context = await global.browser.createBrowserContext(contextOptions).catch(() => null);
        usePool = false;
      } else if (ENABLE_CONTEXT_POOL) {
        // 无代理 - 尝试使用上下文池
        try {
          const poolResult = await contextPool.acquire(reqId);
          context = poolResult.context;
          usePool = true;
          logger.poolAcquire(reqId, contextPool.getTotalSize(), contextPool.availableContexts.length);
        } catch (poolError) {
          // 池获取失败，回退到独立创建
          logger.warn('上下文池', `获取失败，回退独立创建: ${poolError.message}`, { id: reqId });
          context = await global.browser.createBrowserContext().catch(() => null);
          usePool = false;
        }
      } else {
        // 池未启用 - 创建独立上下文
        context = await global.browser.createBrowserContext().catch(() => null);
        usePool = false;
      }

      if (!context) {
        await cleanup(false);
        return reject("Failed to create browser context");
      }

      // 设置超时
      timeoutId = setTimeout(async () => {
        if (!isResolved) {
          logger.requestTimeout(reqId, Date.now() - startTime);
          await cleanup(false);
          reject(`Timeout for ${reqId}`);
        }
      }, global.timeOut || 120000);

      page = await context.newPage();

      // 代理认证
      if (proxy?.username && proxy?.password) {
        await page.authenticate({ username: proxy.username, password: proxy.password });
      }

      // 设置请求拦截 - 优化资源加载
      await page.setRequestInterception(true);

      page.on("request", async (request) => {
        try {
          const reqUrl = request.url();
          const resourceType = request.resourceType();

          // 拦截主文档请求，返回fakePage
          if ([url, url + "/"].includes(reqUrl) && resourceType === "document") {
            const body = fakePageTemplate
              ? fakePageTemplate.replace(/<site-key>/g, siteKey)
              : `<html><body><div class="turnstile" data-sitekey="${siteKey}"></div></body></html>`;

            await request.respond({
              status: 200,
              contentType: "text/html",
              body: body
            });
            return;
          }

          // 允许 Cloudflare 相关资源（优先放行）
          if (reqUrl.includes('cloudflare.com') || reqUrl.includes('challenges.cloudflare.com')) {
            await request.continue();
            return;
          }

          // 阻止不必要的资源类型
          if (BLOCKED_RESOURCE_TYPES.has(resourceType)) {
            await request.abort();
            return;
          }

          // 阻止分析/广告脚本
          if (shouldBlockUrl(reqUrl)) {
            await request.abort();
            return;
          }

          // 其他资源正常加载
          await request.continue();
        } catch (e) {
          // 请求可能已经被处理
        }
      });

      // 页面加载
      await page.goto(url, {
        waitUntil: "domcontentloaded",
        timeout: 60000
      });

      // 等待并获取token - 简化的重试逻辑
      let token = null;
      const maxAttempts = 2;
      const baseTimeout = 45000;

      for (let attempt = 1; attempt <= maxAttempts && !token; attempt++) {
        try {
          // 等待token元素出现
          await page.waitForSelector('[name="cf-response"]', {
            timeout: baseTimeout
          });

          // 获取并验证token
          token = await page.evaluate(() => {
            const el = document.querySelector('[name="cf-response"]');
            const val = el?.value;
            if (val && val.length > 100 && val.startsWith('0.') && val.includes('.')) {
              return val;
            }
            return null;
          });

          if (token && validateToken(token)) {
            logger.tokenSuccess(reqId, token.length, attempt);
            break;
          }

          // 重试前刷新
          if (attempt < maxAttempts) {
            await page.reload({ waitUntil: 'domcontentloaded', timeout: 15000 }).catch(() => {});
          }
        } catch (e) {
          if (attempt === maxAttempts) throw e;
        }
      }

      // 清理并返回结果
      if (token && validateToken(token)) {
        await cleanup(true);
        return resolve(token);
      }

      await cleanup(false);
      return reject(`Failed to get token for ${reqId}`);

    } catch (e) {
      await cleanup(false);
      reject(e.message || 'Unknown error');
    }
  });
}

module.exports = solveTurnstileMin;
